// Progressive enhancement for focusgroup on browsers without native support
if (!Object.hasOwn(HTMLElement.prototype, 'focusGroup')) {
  import('https://esm.sh/@microsoft/focusgroup-polyfill')
    .then(({ polyfill }) => polyfill())
    .catch(() => {});
}

const tabs = Array.from(document.querySelectorAll('.tablist > button'));
const panels = Array.from(document.querySelectorAll('[role="tabpanel"]'));
const tablist = document.querySelector('.tablist');

function selectTab(targetTab, { focus = false, updateHash = true } = {}) {
  const targetPanel = panels.find((p) => p.getAttribute('aria-labelledby') === targetTab.id);
  if (targetTab.getAttribute('aria-selected') === 'true' && targetPanel && !targetPanel.hidden) {
    if (focus) targetTab.focus();
    return;
  }
  for (const tab of tabs) {
    const active = tab === targetTab;
    tab.ariaSelected = String(active);
    tab.toggleAttribute('focusgroupstart', active);
  }
  for (const panel of panels) {
    const match = panel.getAttribute('aria-labelledby') === targetTab.id;
    if (match) {
      panel.hidden = false;
      panel.tabIndex = 0;
    } else {
      panel.setAttribute('hidden', 'until-found');
      panel.removeAttribute('tabindex');
    }
  }
  targetTab.scrollIntoView({ block: 'nearest', inline: 'nearest', container: 'nearest' });
  if (focus) targetTab.focus();
  if (updateHash && targetTab.dataset.hash) {
    history.replaceState(null, '', '#' + targetTab.dataset.hash);
  }
}

for (const tab of tabs) {
  tab.addEventListener('click', () => selectTab(tab));
  tab.addEventListener('focus', () => selectTab(tab));
  tab.addEventListener('keydown', (e) => {
    const idx = tabs.indexOf(tab);
    let next = null;
    if (e.key === 'ArrowRight') next = tabs[(idx + 1) % tabs.length];
    else if (e.key === 'ArrowLeft') next = tabs[(idx - 1 + tabs.length) % tabs.length];
    else if (e.key === 'Home') next = tabs[0];
    else if (e.key === 'End') next = tabs[tabs.length - 1];
    if (next) {
      e.preventDefault();
      selectTab(next, { focus: true });
    }
  });
}

// Reveal matching tab when browser Find-in-Page matches inside hidden="until-found"
for (const panel of panels) {
  panel.addEventListener('beforematch', () => {
    const tabId = panel.getAttribute('aria-labelledby');
    const tab = tabs.find((t) => t.id === tabId);
    if (tab) selectTab(tab, { focus: false, updateHash: true });
  });
}

function syncHash() {
  const hash = location.hash.replace('#', '').toLowerCase();
  const hit = tabs.find((t) => t.dataset.hash === hash);
  if (hit) selectTab(hit, { focus: false, updateHash: false });
}
window.addEventListener('hashchange', syncHash);
syncHash();

// Search & Filter Logic for Track 1 Finds
const qInput = document.getElementById('q');
const episodeSelect = document.getElementById('episode-filter');
const filterForm = document.getElementById('filter-form');
const budgetRadios = Array.from(document.querySelectorAll('input[name="budget"]'));
const categoryButtons = Array.from(document.querySelectorAll('[data-category]'));
const gridEl = document.getElementById('product-grid');
const emptyEl = document.getElementById('empty-state');
const countEl = document.getElementById('visible-count');
const resetBtn = document.getElementById('reset-filters');

let activeCategory = 'All Categories';

function escapeTxt(str) {
  const d = document.createElement('div');
  d.textContent = str;
  return d.innerHTML;
}

function renderCards() {
  const query = (qInput.value || '').trim().toLowerCase();
  const maxBudget = Number(budgetRadios.find((r) => r.checked)?.value || 0);
  const selectedEp = episodeSelect.value;

  const filtered = CATALOG.filter((it) => {
    if (maxBudget > 0 && (it.priceNum <= 0 || it.priceNum > maxBudget)) return false;
    if (activeCategory !== 'All Categories' && !it.categories.includes(activeCategory)) return false;
    if (selectedEp !== 'all' && !it.episodes.some((e) => e.id === selectedEp)) return false;
    if (query) {
      const hay = [
        it.title,
        it.subtitle,
        it.shopeeTitle,
        it.trap,
        it.rightAnswer,
        ...it.episodes.map((e) => e.label),
      ].join(' ').toLowerCase();
      if (!hay.includes(query)) return false;
    }
    return true;
  });

  countEl.textContent = String(filtered.length);
  if (filtered.length === 0) {
    gridEl.innerHTML = '';
    gridEl.hidden = true;
    emptyEl.hidden = false;
    return;
  }

  emptyEl.hidden = true;
  gridEl.hidden = false;
  gridEl.innerHTML = filtered
    .map((it) => {
      const epTag = it.episodes[0]?.label.split('·')[0].trim() || 'Tested';
      return `<article class="product-card" style="--card-accent: ${escapeTxt(it.accent)}">
        <img src="${escapeTxt(it.webpRel)}" alt="${escapeTxt(it.title)}" width="256" height="256" loading="lazy">
        <header class="card-header">
          <div class="badge-row">
            <span class="cat-tag">${escapeTxt(epTag)} · ${escapeTxt(it.primaryCategory)}</span>
          </div>
          <h3><a class="card-link" href="${escapeTxt(it.shortUrl)}" target="_blank" rel="sponsored noopener">${escapeTxt(it.title)}</a></h3>
          <p class="card-subtitle">${escapeTxt(it.subtitle)}</p>
        </header>
        <div class="card-body">
          <p class="myth-line">✗ ${escapeTxt(it.trap)}</p>
          <p class="fact-line">✓ ${escapeTxt(it.rightAnswer)}</p>
        </div>
        <footer class="card-footer">
          <span class="price-tag">${escapeTxt(it.priceDisplay)}</span>
          <span class="cta-tag">Shop Deal →</span>
        </footer>
      </article>`;
    })
    .join('');
}

filterForm.addEventListener('submit', (e) => {
  e.preventDefault();
  renderCards();
});
qInput.addEventListener('input', renderCards);
episodeSelect.addEventListener('change', renderCards);
budgetRadios.forEach((r) => r.addEventListener('change', renderCards));
categoryButtons.forEach((btn) => {
  btn.addEventListener('click', () => {
    activeCategory = btn.dataset.category || 'All Categories';
    categoryButtons.forEach((b) => b.setAttribute('aria-pressed', String(b === btn)));
    renderCards();
  });
});
resetBtn.addEventListener('click', () => {
  qInput.value = '';
  episodeSelect.value = 'all';
  budgetRadios[0].checked = true;
  activeCategory = 'All Categories';
  categoryButtons.forEach((b, i) => b.setAttribute('aria-pressed', String(i === 0)));
  renderCards();
  qInput.focus();
});

// Track 3: Interactive 2026 PH 13th-Month Calculator
const calcBasic = document.getElementById('calc-basic');
const calcMonths = document.getElementById('calc-months');
const calcOther = document.getElementById('calc-other');

const out13th = document.getElementById('out-13th');
const outExempt = document.getElementById('out-exempt');
const outTaxable = document.getElementById('out-taxable');
const outSavings = document.getElementById('out-savings');
const outDebt = document.getElementById('out-debt');
const outRegalo = document.getElementById('out-regalo');
const outHandaan = document.getElementById('out-handaan');
const outBuffer = document.getElementById('out-buffer');

function parsePesoInput(el, fallback = 0) {
  const n = Number(String(el.value || '').replace(/[^0-9.]/g, ''));
  return Number.isFinite(n) ? n : fallback;
}

function fmtPhp(val) {
  return '₱' + Math.round(val).toLocaleString('en-US');
}

function updateCalc() {
  const monthlyBasic = Math.max(0, parsePesoInput(calcBasic, 28000));
  const monthsWorked = Math.min(12, Math.max(0, parsePesoInput(calcMonths, 12)));
  const otherBonus = Math.max(0, parsePesoInput(calcOther, 0));

  const thirteenth = (monthlyBasic * monthsWorked) / 12;
  const combined = thirteenth + otherBonus;
  const exempt = Math.min(90000, combined);
  const taxableExcess = Math.max(0, combined - 90000);
  const netEst = Math.max(0, combined - taxableExcess * 0.2);

  out13th.textContent = fmtPhp(thirteenth);
  outExempt.textContent = fmtPhp(exempt);
  outTaxable.textContent = fmtPhp(taxableExcess);
  outSavings.textContent = fmtPhp(netEst * 0.30);
  outDebt.textContent = fmtPhp(netEst * 0.25);
  outRegalo.textContent = fmtPhp(netEst * 0.20);
  outHandaan.textContent = fmtPhp(netEst * 0.15);
  outBuffer.textContent = fmtPhp(netEst * 0.10);
}

[calcBasic, calcMonths, calcOther].forEach((el) => el.addEventListener('input', updateCalc));
updateCalc();
